    unit character varying(20) DEFAULT ''::character varying NOT NULL,
    price bigint,
    availability character varying(20) DEFAULT 'in_stock'::character varying NOT NULL,
    image_path character varying(255),
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    in_basket boolean DEFAULT true NOT NULL,
    specs character varying(80) DEFAULT ''::character varying NOT NULL,
    section character varying(40) DEFAULT ''::character varying NOT NULL,
    CONSTRAINT products_availability_check CHECK (((availability)::text = ANY ((ARRAY['in_stock'::character varying, 'on_order'::character varying, 'unavailable'::character varying])::text[])))
);

